#!/usr/bin/env python3
"""Independent endpoint coordinate and lifecycle audit, compact bounded reads."""
from pathlib import Path
import json,hashlib
import numpy as np,pandas as pd,pyarrow.parquet as pq
R=Path(__file__).resolve().parents[1];B=R.parent;O=Path(__file__).resolve().parent/'wave2';O.mkdir(exist_ok=True)
def norm(s):
 z=s.astype('string').str.strip();return pd.to_numeric(z.where(z.str.fullmatch(r'\d{10,11}',na=False)).str.zfill(11),errors='coerce').fillna(0).to_numpy(dtype=np.uint64)
def read(year):
 file=R/f'economy/remote_address_selected/rfsd_{year}_address_lifecycle_selected.parquet';out={x:[] for x in ['inn','code','lat','lon','quality','creation','dissolution']}
 for b in pq.ParquetFile(file).iter_batches(batch_size=100000):
  d=b.to_pandas();d=d[d.inn.astype('string').str.fullmatch(r'\d{10}',na=False)].copy();out['inn'].append(d.inn.to_numpy().astype(np.uint64));out['code'].append(norm(d.oktmo));out['lat'].append(d.lat.to_numpy());out['lon'].append(d.lon.to_numpy());out['quality'].append(d.geocoding_quality.isin(['house','street']).to_numpy())
  for src,dst in [('creation_date','creation'),('dissolution_date','dissolution')]:out[dst].append(d[src].to_numpy(dtype='datetime64[D]'))
 return {k:np.concatenate(v) for k,v in out.items()}
def main():
 candidates=list((R/'economy').glob('**/ADDRESS_AUDIT.json'))
 if not candidates:raise RuntimeError('Author endpoint audit not yet written; no inferred zero')
 authorpath=candidates[0];author=json.loads(authorpath.read_text());a,b=read(2021),read(2025);common,ia,ib=np.intersect1d(a['inn'],b['inn'],assume_unique=True,return_indices=True);p=pd.read_parquet(B/'anchor_research_20261019/data/point_axis.parquet',columns=['id','oktmo_2021']);lookup=pd.Series(np.arange(len(p),dtype=np.int32),index=norm(p.oktmo_2021));old=pd.Series(a['code'][ia]).map(lookup).fillna(-1).to_numpy(dtype=np.int32);new=pd.Series(b['code'][ib]).map(lookup).fillna(-1).to_numpy(dtype=np.int32);valid=np.isfinite(a['lat'][ia])&np.isfinite(a['lon'][ia])&np.isfinite(b['lat'][ib])&np.isfinite(b['lon'][ib])&(abs(a['lat'][ia])<=90)&(abs(b['lat'][ib])<=90)&(abs(a['lon'][ia])<=180)&(abs(b['lon'][ib])<=180)
 la=np.deg2rad(a['lat'][ia]);lb=np.deg2rad(b['lat'][ib]);dl=np.deg2rad(b['lon'][ib]-a['lon'][ia]);cross=np.sqrt((np.cos(lb)*np.sin(dl))**2+(np.cos(la)*np.sin(lb)-np.sin(la)*np.cos(lb)*np.cos(dl))**2);dot=np.sin(la)*np.sin(lb)+np.cos(la)*np.cos(lb)*np.cos(dl);dd=6371.0088*np.arctan2(cross,dot);q=a['quality'][ia]&b['quality'][ib];exact=valid&(a['lat'][ia]==b['lat'][ib])&(a['lon'][ia]==b['lon'][ib]);stable=valid&(dd<=.1)&q;cc=(a['code'][ia]>0)&(b['code'][ib]>0)&(a['code'][ia]!=b['code'][ib]);both=(old>=0)&(new>=0);lost=(old>=0)&(new<0)
 stats={'common_INN':len(common),'common_same_native_exact_point':int((both&(old==new)).sum()),'common_different_native_exact_points':int((both&(old!=new)).sum()),'native_exact2021_only':int(lost.sum()),'native_exact2025_only':int(((old<0)&(new>=0)).sum()),'neither_native_exact':int(((old<0)&(new<0)).sum()),'common_reported_code_changed_valid_both':int(cc.sum()),'valid_reported_coordinates_both':int(valid.sum()),'house_street_both':int(q.sum()),'exactly_equal_reported_coordinates':int(exact.sum()),'house_street_distance_le100m':int(stable.sum()),'changed_code_stable_reported_coordinates':int((cc&stable).sum()),'lost_native_link_stable_reported_coordinates':int((lost&stable).sum())};checks=[{'name':k,'pass':bool(v==author['summary'][k])} for k,v in stats.items()]
 oldonly=~np.isin(a['inn'],common);newonly=~np.isin(b['inn'],common);end21=np.datetime64('2021-12-31');end25=np.datetime64('2025-12-31');life={'only_INN_2021':int(oldonly.sum()),'only_INN_2025':int(newonly.sum()),'only2021_dissolution_known_le2025':int((oldonly&~np.isnat(a['dissolution'])&(a['dissolution']<=end25)).sum()),'only2021_dissolution_known_after2021_le2025':int((oldonly&(a['dissolution']>end21)&(a['dissolution']<=end25)).sum()),'only2021_dissolution_unknown':int((oldonly&np.isnat(a['dissolution'])).sum()),'only2025_creation_after2021_le2025':int((newonly&(b['creation']>end21)&(b['creation']<=end25)).sum()),'only2025_creation_le2021':int((newonly&~np.isnat(b['creation'])&(b['creation']<=end21)).sum())};al=json.loads((authorpath.parent/'LIFECYCLE.json').read_text());checks.extend({'name':k,'pass':bool(v==al[k])} for k,v in life.items())
 life['only2021_dissolution_before_2021']=int((oldonly&(a['dissolution']<np.datetime64('2021-01-01'))).sum());life['only2021_dissolution_within_2021']=int((oldonly&(a['dissolution']>=np.datetime64('2021-01-01'))&(a['dissolution']<=end21)).sum())
 life['all2021_dissolution_before_2021']=int((a['dissolution']<np.datetime64('2021-01-01')).sum());life['all2025_dissolution_before_2025']=int((b['dissolution']<np.datetime64('2025-01-01')).sum())
 table=pd.read_csv(authorpath.parent/'code_address_compatibility.csv');rows=[]
 for cname,cmask in [('all_common',np.ones(len(common),bool)),('changed_valid_code',cc),('lost_native_exact_link',lost),('different_native_exact_points',both&(old!=new))]:
  for qname,qmask in [('any_quality',np.ones(len(common),bool)),('house_street_both',q)]:
   for name,mask in [('exact_equal',exact),('changed_le100m',valid&~exact&(dd<=.1)),('100m_to1km',valid&(dd>.1)&(dd<=1)),('1_to5km',valid&(dd>1)&(dd<=5)),('gt5km',valid&(dd>5)),('coordinate_missing_invalid',~valid)]:
    count=int((cmask&qmask&mask).sum());r=table[table.cohort.eq(cname)&table.quality.eq(qname)&table.coordinate_relation.eq(name)].iloc[0];checks.append({'name':str((cname,qname,name)),'pass':bool(count==r.INN_count)});rows.append(dict(cohort=cname,quality=qname,coordinate_relation=name,count=count))
 pd.DataFrame(rows).to_csv(O/'independent_address_compatibility.csv',index=False);out={'status':'PASS' if all(x['pass'] for x in checks) else 'FAIL','n_checks':len(checks),'checks':checks,'summary':stats,'lifecycle':life,'author_result_SHA256':hashlib.sha256(authorpath.read_bytes()).hexdigest(),'source_SHA256':{str(y):hashlib.sha256((R/f'economy/remote_address_selected/rfsd_{y}_address_lifecycle_selected.parquet').read_bytes()).hexdigest() for y in [2021,2025]},'code_SHA256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'conditional_alias_model_independently_retrained':False,'interpretation':'Coordinate compatibility and legal dates are registration evidence. Same coordinates may be repeated/stale; not proven location of economic activity. Lifecycle is legal, not physical service opening/closure. Aliases remain a nonofficial sensitivity model.'};(O/'ADDRESS_AUDIT.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(out['status'],len(checks),flush=True);assert all(x['pass'] for x in checks)
if __name__=='__main__':main()
